// Alegra devuelve máximo 30 facturas por llamada, así que el nodo anterior
// hace varias llamadas y entrega una página por cada una.
// Aquí las abrimos para quedar con una factura por item.

const facturas = [];

for (const item of items) {
  const cuerpo = item.json;
  if (Array.isArray(cuerpo)) {
    facturas.push(...cuerpo);
  } else if (Array.isArray(cuerpo.data)) {
    facturas.push(...cuerpo.data);
  } else {
    facturas.push(cuerpo);
  }
}

return facturas.map((factura) => ({ json: factura }));

// ─── Puedes cambiar esto ──────────────────────────────────────────────
const DIAS_GRACIA = 0;   // días de gracia antes de empezar a contar mora
const MONEDA = 'COP';    // solo afecta cómo se ve la plata en el detalle
// ──────────────────────────────────────────────────────────────────────

const hoy = new Date();
hoy.setHours(0, 0, 0, 0);
const fechaCorte = hoy.toISOString().slice(0, 10);

const plata = (n) =>
  new Intl.NumberFormat('es-CO', {
    style: 'currency',
    currency: MONEDA,
    maximumFractionDigits: 0,
  }).format(n);

// El nombre del cliente llega distinto según el país. Lo normalizamos.
const nombreDe = (cliente) => {
  const n = cliente && cliente.name;
  if (Array.isArray(n)) return n.filter(Boolean).join(' ');
  if (n && typeof n === 'object') return [n.firstName, n.lastName].filter(Boolean).join(' ');
  return n || 'Cliente sin nombre';
};

const numeroDe = (f) =>
  String((f.numberTemplate && f.numberTemplate.fullNumber) || f.number || f.id);

const estadoDe = (dias) => {
  if (dias <= 0) return 'Al día';
  if (dias <= 30) return 'Mora leve';
  if (dias <= 60) return 'Mora seria';
  return 'Crítico';
};

const porCliente = new Map();

for (const item of items) {
  const f = item.json;

  // El saldo pendiente viene en 'balance'. Si esa cuenta no lo trae,
  // lo deducimos del total menos lo ya pagado.
  const saldo = Number(
    f.balance ?? Number(f.total ?? 0) - Number(f.totalPaid ?? 0)
  );
  if (!(saldo > 0)) continue;

  const cliente = f.client || {};
  const clave = String(cliente.id ?? nombreDe(cliente));

  let mora = 0;
  if (f.dueDate) {
    const vence = new Date(f.dueDate + 'T00:00:00');
    mora = Math.floor((hoy - vence) / 86400000) - DIAS_GRACIA;
  }

  if (!porCliente.has(clave)) {
    porCliente.set(clave, {
      cliente: nombreDe(cliente),
      saldoTotal: 0,
      vencido: 0,
      tramo1a30: 0,
      tramo31a60: 0,
      tramoMas60: 0,
      diasMora: 0,
      cantidad: 0,
      lineas: [],
    });
  }

  const c = porCliente.get(clave);
  c.saldoTotal += saldo;
  c.cantidad += 1;

  if (mora > 0) {
    c.vencido += saldo;
    if (mora <= 30) c.tramo1a30 += saldo;
    else if (mora <= 60) c.tramo31a60 += saldo;
    else c.tramoMas60 += saldo;
  }

  if (mora > c.diasMora) c.diasMora = mora;

  c.lineas.push(
    numeroDe(f) +
      ': ' +
      plata(saldo) +
      (mora > 0 ? ' — ' + mora + ' días de mora' : ' — aún no vence')
  );
}

const salida = [...porCliente.values()]
  .filter((c) => c.vencido > 0)
  .map((c) => ({
    cliente: c.cliente,
    saldoTotal: Math.round(c.saldoTotal),
    vencido: Math.round(c.vencido),
    tramo1a30: Math.round(c.tramo1a30),
    tramo31a60: Math.round(c.tramo31a60),
    tramoMas60: Math.round(c.tramoMas60),
    diasMora: c.diasMora,
    estado: estadoDe(c.diasMora),
    // Prioridad: pesa la plata vencida por los días que lleva vencida.
    prioridad: Math.round((c.vencido * Math.max(c.diasMora, 1)) / 1000),
    detalle: (c.cantidad + ' factura(s) pendiente(s):\n' + c.lineas.join('\n')).slice(0, 1900),
    fechaCorte,
  }))
  .sort((a, b) => b.prioridad - a.prioridad);

return salida.map((c) => ({ json: c }));
